mapper.select:
SELECT t.*, o.order_code, p.product_name, r.resource_name FROM mes_production_task t LEFT JOIN mes_production_order o ON t.order_id = o.id LEFT JOIN mes_product_definition p ON t.product_id = p.id LEFT JOIN mes_production_resource r ON t.resource_id = r.id WHERE t.is_deleted = 0
AND t.task_code LIKE CONCAT('%', #{taskCode}, '%')
AND t.order_id = #{orderId}
AND t.resource_id = #{resourceId}
AND t.status = #{status}
ORDER BY t.create_time DESC
